from __future__ import annotations
from math import atan, log

def scalar_defect(t: float) -> float:
    """The scalar unitary defect |Log(1+it)|^2 - 1."""
    return 0.25 * log(1.0 + t * t) ** 2 + atan(t) ** 2 - 1.0

def unit_circle_root(lower: float, upper: float, tolerance: float = 1e-12) -> tuple[float, float]:
    """Return a bracket enclosing a scalar unit-circle intersection."""
    f_lower = scalar_defect(lower)
    if f_lower * scalar_defect(upper) > 0.0:
        raise ValueError("the endpoints do not bracket a root")
    while upper - lower > tolerance:
        middle = 0.5 * (lower + upper)
        if f_lower * scalar_defect(middle) <= 0.0:
            upper = middle
        else:
            lower = middle
            f_lower = scalar_defect(lower)
    return lower, upper
